stop() {
    if (this.pollInterval) clearInterval(this.pollInterval);

    if (this.process) {
      this.sendLog('[System] Stopping Satisfactory Server...');
      if (this.process.pid) {
        if (process.platform === 'win32') {
          spawn('taskkill', ['/pid', this.process.pid.toString(), '/f', '/t']);
        } else {
          this.process.kill();
        }
      }
